#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);
    // Check for conversion failure or extra characters
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 1) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    long steps = 0;
    long value = n;
    while (value != 1) {
        if ((value & 1) == 0) {
            value >>= 1;
        } else {
            // Check for potential overflow before multiplication
            // The original program checks after the operation, but we mimic the same limit.
            value = value * 3 + 1;
        }
        steps++;
        if (steps > 999999) {
            puts("STEP_LIMIT_EXCEEDED");
            return 0;
        }
        if (value > 1000000000000000L) {
            puts("OVERFLOW_GUARD");
            return 0;
        }
    }
    printf("n=%ld steps=%ld\n", n, steps);
    return 0;
}
